{
  "name": "PTC PCR热循环仪",
  "name_en": "PTC PCR Thermal Cycler",
  "manufacturer": "",
  "description": "用于PCR温度循环实验的热循环仪，可读取温度与运行状态，控制热盖开合与压力，并管理、运行和删除仪器中的程序。",
  "description_en": "A PCR thermal cycler used for temperature cycling experiments. It can report temperature and run status, control heated-lid open/close and lid force, and manage, run, and delete onboard programs.",
  "actions": [
    {
      "action_name": "auto-cancel",
      "description": "取消当前运行中的程序或操作。",
      "description_en": "Cancel the currently running program or operation."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与热循环仪的连接或会话。",
      "description_en": "Close the connection or session with the thermal cycler."
    },
    {
      "action_name": "auto-erase",
      "description": "删除仪器中指定的程序。",
      "description_en": "Delete a specified program stored on the instrument."
    },
    {
      "action_name": "auto-execute",
      "description": "向仪器发送并执行底层命令。",
      "description_en": "Send and execute a low-level command on the instrument."
    },
    {
      "action_name": "auto-folders",
      "description": "列出仪器中的程序文件夹。",
      "description_en": "List program folders stored on the instrument."
    },
    {
      "action_name": "auto-geterrors",
      "description": "获取仪器当前错误信息。",
      "description_en": "Get current error information from the instrument."
    },
    {
      "action_name": "auto-getlidstatus",
      "description": "获取热盖状态。",
      "description_en": "Get the heated lid status."
    },
    {
      "action_name": "auto-getstatus",
      "description": "获取仪器当前运行状态。",
      "description_en": "Get the current operating status of the instrument."
    },
    {
      "action_name": "auto-gettemp",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    },
    {
      "action_name": "auto-lidclose",
      "description": "关闭热盖。",
      "description_en": "Close the heated lid."
    },
    {
      "action_name": "auto-lidopen",
      "description": "打开热盖。",
      "description_en": "Open the heated lid."
    },
    {
      "action_name": "auto-program",
      "description": "在仪器中创建或写入程序。",
      "description_en": "Create or write a program on the instrument."
    },
    {
      "action_name": "auto-programs",
      "description": "列出指定文件夹中的程序。",
      "description_en": "List programs in a specified folder."
    },
    {
      "action_name": "auto-run",
      "description": "运行指定名称的程序。",
      "description_en": "Run a program by name."
    },
    {
      "action_name": "auto-setdebug",
      "description": "设置或启用调试模式。",
      "description_en": "Set or enable debug mode."
    },
    {
      "action_name": "auto-setlidforce",
      "description": "设置热盖压紧力度。",
      "description_en": "Set the heated lid clamping force."
    },
    {
      "action_name": "auto-version",
      "description": "获取仪器版本信息。",
      "description_en": "Get the instrument version information."
    },
    {
      "action_name": "auto-update",
      "description": "刷新或更新仪器状态信息。",
      "description_en": "Refresh or update instrument status information."
    },
    {
      "action_name": "auto-clearbesr",
      "description": "清除BESR状态或错误寄存器信息。",
      "description_en": "Clear BESR status or error register information."
    }
  ],
  "tag_hints": [
    "PCR thermal cycler",
    "temperature cycling",
    "heated lid control",
    "PCR program management",
    "thermal block temperature",
    "protocol storage",
    "instrument status and errors"
  ]
}

